const menu=document.querySelector(".menu-toggle");const nav=document.querySelector(".navbar nav");if(menu&&nav){menu.addEventListener("click",()=>{const open=nav.classList.toggle("open");menu.setAttribute("aria-expanded",String(open))});nav.querySelectorAll("a").forEach(link=>link.addEventListener("click",()=>{nav.classList.remove("open");menu.setAttribute("aria-expanded","false")}))}document.querySelectorAll(".cta-form").forEach(form=>form.addEventListener("submit",event=>{event.preventDefault();const button=form.querySelector("button");button.firstChild.textContent="Thank you — we'll be in touch ";button.setAttribute("disabled","true")}));
